// Standardized filter datasets — single source of truth for every
// Country / City / Language / Skill / Industry list in the product.
// Data lives in api/src/datasets/*.ts (generated by
// scripts/generate-filter-datasets.py); the web app never duplicates it,
// it fetches it from GET /profiles/datasets and the filter-options
// endpoints. Stored profile/campaign values keep their existing shape
// (country/city strings, languages/skills/industries text[]), so no
// migration is needed — the dataset only constrains what NEW values
// can be picked.
import { COUNTRIES, COUNTRY_NAMES, type DatasetCountry } from './countries';
import { CITIES_BY_COUNTRY } from './cities';
import { LANGUAGES, LANGUAGE_NAMES, type DatasetLanguage } from './languages';
import { SKILLS } from './skills';
import { INDUSTRIES } from './industries';

export { COUNTRIES, COUNTRY_NAMES, CITIES_BY_COUNTRY, LANGUAGES, LANGUAGE_NAMES, SKILLS, INDUSTRIES };
export type { DatasetCountry, DatasetLanguage };

/** Match an ISO alpha-2 code ("GB") or a country name ("United Kingdom", case-insensitive). */
export function resolveCountryCode(input: string | undefined | null): string | null {
  if (!input) return null;
  const needle = input.trim();
  if (!needle) return null;
  const byCode = COUNTRIES.find((c) => c.code.toLowerCase() === needle.toLowerCase());
  if (byCode) return byCode.code;
  const byName = COUNTRIES.find((c) => c.name.toLowerCase() === needle.toLowerCase());
  return byName ? byName.code : null;
}

export function resolveCountryName(input: string | undefined | null): string | null {
  const code = resolveCountryCode(input);
  if (!code) return null;
  return COUNTRIES.find((c) => c.code === code)?.name ?? null;
}

/** Cities for a country (ISO code or name). Unknown/empty input -> []. */
export function citiesForCountry(input: string | undefined | null): string[] {
  const code = resolveCountryCode(input);
  if (!code) return [];
  return CITIES_BY_COUNTRY[code] ?? [];
}

/** The form dataset: countries as {code, name} (cities are per-country, fetched separately). */
export function getDatasets() {
  return {
    countries: COUNTRIES,
    languages: LANGUAGE_NAMES,
    skills: SKILLS,
    industries: INDUSTRIES,
  };
}

/** Filter-options shape (backward-compatible with the old DISTINCT endpoints). */
export function getFilterOptions(country?: string) {
  return {
    countries: COUNTRY_NAMES,
    cities: country ? citiesForCountry(country) : [],
    languages: LANGUAGE_NAMES,
    skills: SKILLS,
    industries: INDUSTRIES,
  };
}
